-- ===== BEGIN zzzzzzzab-a1-unit-05-reuse-fix.sql =====
-- German A1 Unit 5 reuses the frozen Pre-A1 price lexeme and its attested form.
-- Keep canonical level metadata unchanged after the A1 shopping migration; never touch audio state.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
START TRANSACTION;
UPDATE lexemes
SET cefr_level='Pre-A1',
    translation_fa='قیمت داشتن / هزینه داشتن',
    usage_note_fa='در این سطح فقط برای پرسیدن و گفتن قیمت یک چیز در جمله‌های خیلی کوتاه استفاده می‌شود.'
WHERE lexeme_key='lex-de-kosten';
UPDATE lexeme_forms
SET notes='در پرسش‌ها و پاسخ‌های قیمت منبع، «kostet» به‌صورت سوم‌شخص مفرد حال استفاده شده است.'
WHERE lexeme_form_key='lexform-de-kosten-kostet';
COMMIT;

-- ===== END zzzzzzzab-a1-unit-05-reuse-fix.sql =====

-- ===== BEGIN zzzzzzzac-a1-unit-06-food-order.sql =====
-- German A1 Unit 6 — multi-item food/drink ordering and simple preference.
-- Base content never overwrites generated audio state.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @jonas := (SELECT id FROM characters WHERE character_key='char-de-jonas' LIMIT 1);
