INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-clarify-slowly',@level,'آیریس یک پرسش ساده به پاول می‌گوید؛ پاول درخواست می‌کند دوباره و آهسته‌تر گفته شود، آیریس همان پرسش منبع‌دار را تکرار می‌کند و پاول پاسخ مثبت کوتاه می‌دهد.','app','درخواست تکرار با تکرار دقیق همان پرسش پاسخ داده می‌شود و پاسخ کوتاه «Ja.» گفت‌وگو را طبیعی می‌بندد. سه متن نخست عین دو منبع آموزشی‌اند و نوبت چهارم فقط حرف بزرگ و نقطه را به سرواژهٔ منبع‌دار «ja» اضافه می‌کند.')
ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),scenario=VALUES(scenario),opening_initiator=VALUES(opening_initiator),scene_quality_rationale=VALUES(scene_quality_rationale);
