INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES
('de-a1-lesson-personal-form-signs',@level,@unit,15,1,'فرم را پر کن، تابلو را بخوان','Vorname / Familienname / Adresse / Stadt — common signs','نام کوچک، نام خانوادگی، نشانی، شهر و تابلوهای رایج','draft','درس با بازیابی اطلاعات شخصی شروع می‌شود؛ سپس برچسب‌های فرم، تکمیل یک فیلد واقعی، خواندن چهار تابلوی کوتاه و در پایان خواندن حروف برای هجی‌کردن تمرین می‌شوند.','ترتیب از تعامل آشنا به خواندن فرم، تولید هدایت‌شده، خواندن متن محیطی و سپس وضوح تلفظ حروف حرکت می‌کند.','conversation_speaking>matching>fill_blank>matching>pronunciation_read','blocked_until_level_final','درس نخست واحد پایانی، فرم و تابلو و هجی را در یک مسیر کاربردی ترکیب می‌کند.'),
('de-a1-lesson-short-phone-message',@level,@unit,16,2,'لطفاً دوشنبه دوباره تماس بگیرید','Rufen Sie bitte am Montag noch einmal an.','لطفاً دوشنبه دوباره تماس بگیرید','draft','گفت‌وگو هماهنگی کوتاه را می‌سازد؛ سپس یک پیام مستقل شنیده می‌شود، چهار پیام زمانی خوانده و تطبیق داده می‌شوند، یک پیام با انتخاب زمان مناسب کامل می‌شود و در پایان یک پیام دیگر بازسازی می‌شود.','درس از تعامل به دریافت شنیداری، سپس خواندن چند نمونه، تکمیل هدایت‌شدهٔ پیام و در پایان بازسازی کامل یک پیام کوتاه حرکت می‌کند.','conversation_speaking>listen_choose>matching>fill_blank>word_order','blocked_until_level_final','درس دوم واحد پایانی، پیام کوتاه را در دریافت شنیداری، خواندن و تولید هدایت‌شده پوشش می‌دهد.')
ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),unit_id=VALUES(unit_id),sequence_index=VALUES(sequence_index),position_in_unit=VALUES(position_in_unit),title_fa=VALUES(title_fa),source_title=VALUES(source_title),source_title_fa=VALUES(source_title_fa),status=VALUES(status),activity_selection_rationale=VALUES(activity_selection_rationale),sequence_rationale=VALUES(sequence_rationale),template_signature=VALUES(template_signature),notes=VALUES(notes);
SET @l1=(SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-personal-form-signs'); SET @l2=(SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-short-phone-message');

