INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-personal-form-review',@level,'آیریس در یک ثبت‌نام کوتاه اطلاعات پایهٔ پاول را مرور می‌کند: سلام، نام و محل زندگی.','app','شش نوبت عین نمونه‌های منبع‌دار سطح پیشین‌اند و فقط در یک موقعیت ثبت‌نام کوتاه دوباره کنار هم قرار گرفته‌اند؛ هیچ متن آلمانی تازه‌ای برای فرم ساخته نشده است.'),
('dlg-de-a1-short-message-coordination',@level,'آیریس و پاول در یک تماس کوتاه دو کار را هماهنگ می‌کنند: تماس دوباره برای فردا و گرفتن بلیت‌ها در فردا.','app','چهار نوبت از دو جفت پرسش‌وپاسخ مجاور بخش ۱۰۱۰ عیناً حفظ شده‌اند. با توجه به بافت نزدیک منبع که از بلیت‌های تئاتر صحبت می‌کند، «Karten» در ترجمهٔ فارسی به «بلیت‌ها» برگردانده شده است؛ متن آلمانی تغییر نکرده است.')
ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),scenario=VALUES(scenario),opening_initiator=VALUES(opening_initiator),scene_quality_rationale=VALUES(scene_quality_rationale);
SET @d1=(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-personal-form-review'); SET @d2=(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-short-message-coordination');

