('turn-de-a1-form-5',@d1,5,@iris,'app_assigned','unspecified','Wo wohnen Sie?','کجا زندگی می‌کنید؟',FALSE,'blocked_until_level_final'),
('turn-de-a1-form-6',@d1,6,@paul,'app_assigned','unspecified','Ich wohne in Österreich.','من در اتریش زندگی می‌کنم.',TRUE,'blocked_until_level_final'),
('turn-de-a1-message-1',@d2,1,@iris,'app_assigned','unspecified','Können Sie mich morgen noch einmal anrufen?','می‌توانید فردا دوباره با من تماس بگیرید؟',FALSE,'blocked_until_level_final'),
('turn-de-a1-message-2',@d2,2,@paul,'app_assigned','unspecified','Ja, ich rufe Sie morgen noch einmal an.','بله، فردا دوباره با شما تماس می‌گیرم.',TRUE,'blocked_until_level_final'),
