-- ===== BEGIN zzzzzzzzze-a1-coverage-audit.sql =====
-- German A1 whole-level coverage audit mappings.
-- No new learner-facing German is introduced here; this migration connects existing
-- source-backed lesson/activity evidence to the three curriculum targets that were
-- previously unmapped.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;

SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

SET @t_everyday := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-everyday-expressions' LIMIT 1);
SET @t_nouns := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-nouns-articles-plurals' LIMIT 1);
SET @t_cases := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-basic-cases' LIMIT 1);

SET @u_intro := (SELECT id FROM units WHERE unit_key='de-a1-unit-extended-introduction' LIMIT 1);
SET @u_time := (SELECT id FROM units WHERE unit_key='de-a1-unit-time-plans-appointment' LIMIT 1);
SET @u_dir := (SELECT id FROM units WHERE unit_key='de-a1-unit-directions-public-places' LIMIT 1);
SET @u_service := (SELECT id FROM units WHERE unit_key='de-a1-unit-requests-services-help' LIMIT 1);
SET @u_forms := (SELECT id FROM units WHERE unit_key='de-a1-unit-forms-signs-messages' LIMIT 1);

INSERT IGNORE INTO unit_targets(unit_id,curriculum_target_id) VALUES
(@u_service,@t_everyday),
(@u_intro,@t_nouns),
(@u_forms,@t_nouns),
(@u_time,@t_cases),
(@u_dir,@t_cases);

SET @l_work := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-work-and-languages' LIMIT 1);
SET @l_time := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-time-class-schedule' LIMIT 1);
SET @l_appt := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-time-simple-appointment' LIMIT 1);
SET @l_dir := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-ask-and-follow-directions' LIMIT 1);
SET @l_service := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-clarify-permission-help' LIMIT 1);
SET @l_forms := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-personal-form-signs' LIMIT 1);

INSERT IGNORE INTO lesson_targets(lesson_id,curriculum_target_id,coverage_role) VALUES
(@l_service,@t_everyday,'introduce'),
(@l_work,@t_nouns,'practice'),
(@l_forms,@t_nouns,'support'),
(@l_time,@t_cases,'practice'),
(@l_appt,@t_cases,'practice'),
(@l_dir,@t_cases,'practice');

SET @a_service := (SELECT id FROM activities WHERE activity_key='act-de-a1-service-conversation' LIMIT 1);
SET @a_permission := (SELECT id FROM activities WHERE activity_key='act-de-a1-phone-permission-choice' LIMIT 1);
SET @a_help := (SELECT id FROM activities WHERE activity_key='act-de-a1-specific-help-response' LIMIT 1);
SET @a_plural := (SELECT id FROM activities WHERE activity_key='act-de-a1-language-question-order' LIMIT 1);
SET @a_form_nouns := (SELECT id FROM activities WHERE activity_key='act-de-a1-form-fields-matching' LIMIT 1);
SET @a_school_case := (SELECT id FROM activities WHERE activity_key='act-de-a1-time-bis-wann-order' LIMIT 1);
SET @a_concert_case := (SELECT id FROM activities WHERE activity_key='act-de-a1-appointment-invite-order' LIMIT 1);
SET @a_destination_case := (SELECT id FROM activities WHERE activity_key='act-de-a1-directions-question-order' LIMIT 1);

INSERT IGNORE INTO activity_targets(activity_id,curriculum_target_id) VALUES
(@a_service,@t_everyday),
(@a_permission,@t_everyday),
(@a_help,@t_everyday),
(@a_plural,@t_nouns),
(@a_form_nouns,@t_nouns),
(@a_school_case,@t_cases),
(@a_concert_case,@t_cases),
(@a_destination_case,@t_cases);

UPDATE language_levels
SET coverage=JSON_SET(
      coverage,
      '$.gaps[2]','بررسی سراسری ۳۷ هدف نشان داد همهٔ هدف‌ها شواهد آموزشی دارند؛ سه شکاف صرفاً در نگاشت دیتابیس بودند و به محتوای موجود وصل شدند.',
      '$.gaps[3]','پوشش چهار مهارت، تلفظ و الگوهای زبانی اکنون در درس‌های A1 توزیع شده است؛ مرحلهٔ بعد بازبینی سراسری کیفیت و کفایت پوشش، نه افزودن سهمیه‌ای محتوا، است.'
    ),
    notes='ده واحد محتوایی A1 ساخته و بازبینی واحدی شده‌اند. بررسی سراسری همهٔ ۳۷ هدف را به شواهد واقعی درس و فعالیت وصل کرده است. سطح هنوز نهایی نیست؛ قدم بعد بازبینی سراسری پیش از تغییر وضعیت کل سطح است و صوت همچنان تا نهایی‌شدن سطح مسدود می‌ماند.'
WHERE id=@level;

COMMIT;

-- ===== END zzzzzzzzze-a1-coverage-audit.sql =====

-- ===== BEGIN zzzzzzzzzf-a1-review-status.sql =====
-- German A1: move the fully mapped content build into whole-level review.
-- This does not finalize the level and does not unlock or generate audio.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;

SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

UPDATE curriculum_targets ct
SET ct.status='review'
WHERE ct.language_level_id=@level
  AND ct.required_for_completion=TRUE
  AND (
    EXISTS (
      SELECT 1 FROM unit_targets ut
      WHERE ut.curriculum_target_id=ct.id
    )
    OR EXISTS (
      SELECT 1 FROM lesson_targets lt
      WHERE lt.curriculum_target_id=ct.id
    )
    OR EXISTS (
      SELECT 1 FROM activity_targets atg
      WHERE atg.curriculum_target_id=ct.id
    )
  );

UPDATE language_levels
SET status=IF(status='final',status,'review'),
    coverage=JSON_OBJECT(
      'gaps',JSON_ARRAY(
        'همهٔ ۳۷ هدف الزامی به شواهد واقعی واحد، درس یا فعالیت وصل شده‌اند؛ در مرحلهٔ بازبینی باید کفایت هر نگاشت و نبودِ پوشش صوری دوباره بررسی شود.',
        'توازن دشواری، تنوع الگوی فعالیت و توزیع چهار مهارت در کل ۱۶ درس باید به‌صورت سراسری بازبینی شود.',
        'منابع، ترجمه‌های فارسی، ردیابی منبع و طبیعی‌بودن نقش شخصیت‌ها باید یک دور نهایی کنترل کیفیت شوند.',
        'صوت A1 تا نهایی‌شدن کل سطح تولید نمی‌شود و همهٔ موارد صوتی مستقل در این مرحله مسدود می‌مانند.'
      )
    ),
    notes='A1 وارد مرحلهٔ بازبینی سراسری شده است. ده واحد و ۱۶ درس ساخته شده‌اند و همهٔ ۳۷ هدف الزامی نگاشت واقعی دارند. این تغییر به معنی نهایی‌شدن محتوا نیست؛ مرحلهٔ بعد کنترل کیفیت سراسری و رفع فقط ایرادهای واقعی است. صوت تا نهایی‌شدن سطح مسدود می‌ماند.'
WHERE id=@level;

COMMIT;

-- ===== END zzzzzzzzzf-a1-review-status.sql =====

-- ===== BEGIN zzzzzzzzzg-a1-lesson-review-status.sql =====
-- German A1: align every built lesson with whole-level review.
-- This does not finalize content and does not unlock audio.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
UPDATE lessons
SET status=IF(status='final',status,'qa')
WHERE language_level_id=@level;
UPDATE language_levels
SET notes='A1 در مرحلهٔ بازبینی سراسری است. ده واحد و همهٔ ۱۶ درس اکنون در مرحلهٔ کنترل کیفیت هستند و همهٔ ۳۷ هدف الزامی نگاشت واقعی دارند. بازبینی تا اینجا پوشش حرف تعریف، ردیابی منبع، سازگاری نوع خطاب، ترجمه‌های فارسی و تولید هدایت‌شدهٔ نوشتاری را تقویت کرده است. صوت تا نهایی‌شدن سطح مسدود می‌ماند.'
WHERE id=@level;
COMMIT;

-- ===== END zzzzzzzzzg-a1-lesson-review-status.sql =====

-- ===== BEGIN zzzzzzzzzha-a1-reviewed-content-final.sql =====
-- German A1: finalize reviewed lessons and units while keeping the level itself in review.
-- Audio remains blocked because the whole A1 level is not final yet.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @a1_reimport := COALESCE(
  (SELECT is_reimport FROM __a1_reimport_guard WHERE id=1 LIMIT 1),
  0
);

UPDATE lessons
SET status='final'
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0
  AND status IN ('draft','source_checked','cefr_checked','qa');

UPDATE units
SET status='final'
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0
  AND status IN ('draft','review');

UPDATE language_levels
SET status=IF(status='final',status,'review'),
    notes='A1 در مرحلهٔ بازبینی سراسری است. هر ۱۰ واحد و هر ۱۶ درس پس از کنترل کیفیت محتوایی به وضعیت نهایی رسیده‌اند، اما خود سطح هنوز نهایی نشده است. همهٔ ۳۷ هدف الزامی نگاشت واقعی دارند و صوت تا نهایی‌شدن کل سطح مسدود می‌ماند.'
WHERE id=@level
  AND COALESCE(@a1_reimport,0)=0;
COMMIT;

-- ===== END zzzzzzzzzha-a1-reviewed-content-final.sql =====

-- ===== BEGIN zzzzzzzzzhb-a1-finalize-content.sql =====
-- German A1: finalize the content level and unlock audio planning.
-- This migration does not generate audio and never overwrites existing generated assets.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;

SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @a1_reimport := COALESCE(
  (SELECT is_reimport FROM __a1_reimport_guard WHERE id=1 LIMIT 1),
  0
);

UPDATE curriculum_targets
SET status='covered'
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0
  AND required_for_completion=TRUE
  AND status='review';

-- Activity metadata on final lessons is protected by a trigger.
-- Reopen the A1 lessons only inside this transaction, update audio metadata,
-- then restore every lesson to final before committing.
UPDATE lessons
SET status='qa'
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0
  AND status='final';

UPDATE lessons
SET audio_status=CASE
      WHEN audio_status='blocked_until_level_final' THEN 'pending'
      ELSE audio_status
    END
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0;

UPDATE dialogue_turns dt
JOIN dialogues d ON d.id=dt.dialogue_id
SET dt.audio_status=CASE
      WHEN dt.audio_status='blocked_until_level_final' THEN 'pending'
      ELSE dt.audio_status
    END
WHERE d.language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0;

UPDATE activities a
JOIN lessons l ON l.id=a.lesson_id
SET a.audio_status=CASE
      WHEN a.audio_text_target IS NOT NULL
       AND a.audio_status='blocked_until_level_final' THEN 'pending'
      ELSE a.audio_status
    END
WHERE l.language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0;

UPDATE lessons l
SET l.status='final'
WHERE l.language_level_id=@level
  AND l.status='qa'
  AND COALESCE(@a1_reimport,0)=0
  AND EXISTS (
    SELECT 1
    FROM activities a
    WHERE a.lesson_id=l.id
      AND a.position_index=1
      AND a.activity_type='conversation_speaking'
  );

UPDATE lexemes
SET audio_status=CASE
      WHEN audio_status='blocked_until_level_final' THEN 'pending'
      ELSE audio_status
    END
WHERE language_id=@de
  AND cefr_level='A1'
  AND COALESCE(@a1_reimport,0)=0;

UPDATE units
SET status='final'
WHERE language_level_id=@level
  AND COALESCE(@a1_reimport,0)=0;

UPDATE language_levels
SET status='final',
    audio_status='pending',
    coverage=JSON_SET(coverage,'$.gaps',JSON_ARRAY()),
    completion_assessment=JSON_OBJECT(
      'reviewedAt','2026-09-18T04:45:00Z',
      'cefrCoverageComplete',TRUE,
      'progressionComplete',TRUE,
      'practiceAndRetrievalComplete',TRUE,
      'skillModeCoverageComplete',TRUE,
      'requiredGaps',JSON_ARRAY(),
      'qualityReview',JSON_OBJECT(
        'overallScore',9.2,
        'dimensionScores',JSON_OBJECT(
          'cefrCoverage',9.4,
          'pedagogicalProgression',9.2,
          'practiceAndRetrieval',9.1,
          'activityQualityAndVariety',9.0,
          'linguisticAccuracyAndNaturalness',9.3,
          'sourceQualityAndCurrency',9.4,
          'learnerSupportAndClarity',9.1,
          'qaIntegrity',9.3
        ),
        'rationale','پوشش همهٔ ۳۷ هدف الزامی به شواهد واقعی درس و فعالیت متصل است؛ ۱۰ واحد و ۱۶ درس چند دور بازبینی ساختاری، زبانی، منبعی و ترجمه‌ای را گذرانده‌اند. ایرادهای پیدا‌شده در پوشش حرف تعریف، ردیابی منبع، نوع خطاب شخصیت‌ها، چند ترجمهٔ فارسی و تولید نوشتاری هدایت‌شده اصلاح شدند. سطح از نظر محتوایی آمادهٔ نهایی‌شدن است؛ صوت یک فرایند انتشار جداگانه و هنوز در انتظار برنامه‌ریزی و تولید است.',
        'strengths',JSON_ARRAY(
          'همهٔ هدف‌های الزامی A1 نگاشت واقعی به واحد، درس یا فعالیت دارند.',
          'متن آلمانی زبان‌آموز از منابع قابل‌بازاستفاده و بررسی‌شده می‌آید و متن آزادِ ساخته‌شده به محتوای آموزشی وارد نشده است.',
          'ترتیب فعالیت‌ها عمدتاً از فهم و تشخیص به بازیابی و تولید هدایت‌شده حرکت می‌کند.',
          'گفت‌وگوها از نظر نوع خطاب و رابطهٔ شخصیت‌ها بازبینی و اصلاح شده‌اند.',
          'خواندن، شنیدن، گفتار، فرم، تابلو، پیام کوتاه و تلفظ در سطح توزیع شده‌اند.'
        ),
        'remainingWeaknesses',JSON_ARRAY(
          'تولید نوشتاری در ساختار فعلی برنامه هدایت‌شده است و ورودی آزاد تایپی ندارد.',
          'صوت هنوز تولید نشده و کیفیت شنیداری نهایی پس از تولید و اعتبارسنجی فایل‌ها باید جداگانه کنترل شود.'
        )
      ),
      'scopeExclusions',JSON_ARRAY(
        'ورودی آزاد تایپی در ساختار فعلی فعالیت‌ها پشتیبانی نمی‌شود؛ تولید نوشتاری A1 در این نسخه به تکمیل و بازسازی هدایت‌شده محدود است.'
      )
    ),
    notes='A1 از نظر محتوایی نهایی شده است: هر ۱۰ واحد و هر ۱۶ درس نهایی‌اند، همهٔ ۳۷ هدف الزامی پوشش و ارزیابی شده‌اند و شکاف الزامی باز باقی نمانده است. صوت اکنون از حالت مسدود خارج شده و در وضعیت انتظار قرار دارد؛ هنوز هیچ تولید صوت پولی انجام نشده است.'
WHERE id=@level
  AND COALESCE(@a1_reimport,0)=0;

COMMIT;

-- ===== END zzzzzzzzzhb-a1-finalize-content.sql =====

-- ===== BEGIN zzzzzzzzzhc-a1-audio-ready-review.sql =====
-- German A1: align final level metadata after successful audio generation and validation.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;

SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

UPDATE language_levels
SET completion_assessment=JSON_SET(
      completion_assessment,
      '$.reviewedAt','2026-09-18T05:02:00Z',
      '$.qualityReview.rationale','پوشش همهٔ ۳۷ هدف الزامی به شواهد واقعی درس و فعالیت متصل است؛ ۱۰ واحد و ۱۶ درس چند دور بازبینی ساختاری، زبانی، منبعی و ترجمه‌ای را گذرانده‌اند. ایرادهای پیدا‌شده در پوشش حرف تعریف، ردیابی منبع، نوع خطاب شخصیت‌ها، چند ترجمهٔ فارسی و تولید نوشتاری هدایت‌شده اصلاح شدند. هر ۱۶۷ فایل صوتی لازم نیز تولید و از نظر دارایی، نگاشت و سازگاری با پایگاه داده اعتبارسنجی شده‌اند؛ تنها بازبینی شنیداری انسانی برای کنترل کیفیت ادراکی باقی مانده است.',
      '$.qualityReview.remainingWeaknesses',JSON_ARRAY(
        'تولید نوشتاری در ساختار فعلی برنامه هدایت‌شده است و ورودی آزاد تایپی ندارد.',
        'دارایی‌های صوتی و نگاشت آن‌ها به‌صورت فنی اعتبارسنجی شده‌اند، اما بازبینی شنیداری انسانی برای کنترل لحن، تلفظ و طبیعی‌بودن همهٔ فایل‌ها هنوز انجام نشده است.'
      )
    ),
    notes='این سطح از نظر محتوایی و فنی نهایی شده است: هر ۱۰ واحد و هر ۱۶ درس نهایی‌اند، همهٔ ۳۷ هدف الزامی پوشش و ارزیابی شده‌اند و شکاف الزامی باز باقی نمانده است. هر ۱۶۷ فایل صوتی لازم تولید شده‌اند، نگاشت‌ها و دارایی‌ها اعتبارسنجی شده‌اند و وضعیت صوت آماده است؛ بازبینی شنیداری انسانی برای کنترل کیفیت نهایی باقی مانده است.'
WHERE id=@level;

COMMIT;

-- ===== END zzzzzzzzzhc-a1-audio-ready-review.sql =====

-- ===== BEGIN zzzzzzzzzhd-a1-unit-depth-expansion.sql =====
-- German A1: deepen every finalized unit to three pedagogically distinct lessons.
-- Review/retrieval lessons reuse existing source-backed dialogues and add no independent audio targets.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

-- Move every current A1 slot out of the target range before deterministic reordering.
UPDATE lessons
SET sequence_index=sequence_index+2000000,
    position_in_unit=CASE WHEN position_in_unit IS NULL THEN NULL ELSE position_in_unit+200000 END
WHERE language_level_id=@level;

SET @unit := (SELECT id FROM units WHERE unit_key='de-a1-unit-extended-introduction' AND language_level_id=@level LIMIT 1);
INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes)
VALUES('de-a1-lesson-integrated-introduction-review',@level,@unit,3,3,'یک معرفی کامل‌تر بساز',NULL,NULL,'draft','این درس دو محور قبلی واحد، یعنی شغل و زبان، را در یک مرور یکپارچه دوباره فعال می‌کند و از تشخیص به بازیابی می‌رساند.','ابتدا اطلاعات در مکالمه بازیابی می‌شوند، سپس تفاوت معنایی جمله‌ها سنجیده می‌شود و در پایان پرسش شغل بازسازی می‌شود.','conversation_speaking>multiple_choice>word_order','pending','درس تقویتی و بازیابی است؛ متن آلمانی تازهٔ آزاد تولید نمی‌کند و از مواد منبع‌دار موجود استفاده می‌کند.')
ON DUPLICATE KEY UPDATE
 language_level_id=VALUES(language_level_id),unit_id=VALUES(unit_id),sequence_index=VALUES(sequence_index),position_in_unit=VALUES(position_in_unit),
 title_fa=VALUES(title_fa),activity_selection_rationale=VALUES(activity_selection_rationale),sequence_rationale=VALUES(sequence_rationale),
 template_signature=VALUES(template_signature),notes=VALUES(notes);
SET @lesson := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-integrated-introduction-review' LIMIT 1);
UPDATE lessons SET status='qa' WHERE id=@lesson AND status='final';
INSERT IGNORE INTO lesson_targets(lesson_id,curriculum_target_id,coverage_role)
