-- ===== BEGIN zzzzzzzzzzj-a1-replacement-lessons-1.sql =====
-- Replace first seven A1 depth lessons with new source-backed content.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
INSERT IGNORE INTO activity_targets(activity_id,curriculum_target_id) SELECT a.id,ut.curriculum_target_id FROM activities a JOIN unit_targets ut ON ut.unit_id=@unit WHERE a.lesson_id=@lesson;
UPDATE lessons SET status='final',audio_status='pending' WHERE id=@lesson;

