-- ===== PERSIAN EDITORIAL NORMALIZATION FOR DYNAMIC STRUCTURE =====
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
UPDATE language_levels
SET structure_rationale='ساختار A1 از نیاز آموزشی استخراج می‌شود: ابتدا هدف‌های یادگیری و پیش‌نیازها، سپس منابع، توالی آموزشی، مرز درس و طراحی تمرین تعیین می‌شوند و تعدادها در پایان از این تصمیم‌ها به‌دست می‌آیند. بازه‌های تعداد فقط مرزهای کنترل کیفیت هستند. در بازبینی ساختار داینامیک، واحدهای هم‌موضوع ادغام شدند و سطح اکنون ۹ واحد با اندازه‌های ۶، ۳، ۳، ۶، ۳، ۶، ۶، ۳ و ۳ درس دارد؛ این توزیع نتیجهٔ گروه‌بندی آموزشی است نه هدف عددی.',
    notes='A1 شامل ۹ واحد و ۳۹ درس است. چهار جفت واحد هم‌موضوع برای حذف ساختار مصنوعی ۱۳×۳ ادغام شدند؛ هیچ متن آلمانی، گفت‌وگو یا تمرینی به‌خاطر این تغییر بازنویسی نشد. ضعف‌های باقی‌ماندهٔ تمرین/بازیابی و پوشش شیوه‌های مهارتی همچنان صریح ثبت شده‌اند.',
    completion_assessment=JSON_SET(
      completion_assessment,
      '$.qualityReview.rationale','این دور اصلاح کیفیت منبع و چند ضعف روشن سطح A1 را بهبود داده است، اما هنوز نباید کامل تلقی شود. از ۱۴۲ فعالیت، تعداد زیادی همچنان در چند قالب تکرارشونده متمرکزند؛ تمرین مستقل شنیداری فقط در ۱۰ فعالیت و تلفظ فقط در ۳ فعالیت وجود دارد و بازیابی تجمعی به سه ایستگاه مرور بین‌واحدی محدود است. منابع ضعیف نسخهٔ چاپی قدیمی از محتوای نمایش‌داده‌شده به زبان‌آموز کنار گذاشته و فقط برای تحلیل نگه‌داری شده‌اند، اما ممیزی موردبه‌مورد واژگان در برابر فهرست رسمی واژگان سطح A1 مؤسسهٔ گوته هنوز انجام نشده است. نوشتن آزاد نیز به‌علت محدودیت ساختار فعلی فعالیت‌ها جزو دامنهٔ این نسخه نیست. ساختار واحد نیز در بازبینی داینامیک از الگوی ۱۳×۳ خارج و به ۹ Unit نیازمحور بازگروه‌بندی شد، بدون افزودن یا دستکاری متن آلمانی.',
      '$.qualityReview.strengths[0]','۹ واحد و ۳۹ درس با اندازه‌های متفاوت، موقعیت‌های ارتباطی اصلی A1 را با گروه‌بندی نیازمحور پوشش می‌دهند.'
    )
WHERE id=@level;
UPDATE units
SET title_fa='معرفی، کار، زبان‌ها و خانواده',
    grouping_rationale='این واحد شش درس دارد چون یک مسیر پیوستهٔ «شناخت و معرفی افراد» را می‌سازد: سه درس نخست معرفی فرد، شغل و زبان‌ها را گسترش می‌دهند و سه درس بعد همان اطلاعات شخصی را به خانواده و افراد نزدیک منتقل می‌کنند. جداکردن این دو خوشه مرز آموزشی واقعی ایجاد نمی‌کرد و ادغام آن‌ها بازیابی اطلاعات شخصی را در یک بافت تازه ممکن می‌کند؛ شش درس نتیجهٔ این توالی است، نه هدف عددی.',
    notes='واحد معرفی و خانواده در بازبینی ساختار داینامیک ادغام شد؛ هیچ متن آلمانی یا تمرینی تغییر نکرده است.'
WHERE language_level_id=@level AND unit_key='de-a1-unit-extended-introduction';
UPDATE units
SET title_fa='خرید، پرداخت و سفارش غذا',
    grouping_rationale='این واحد شش درس دارد چون دو بخش متوالیِ یک مهارت تراکنشی روزمره را پوشش می‌دهد: ابتدا انتخاب کالا، مقدار، قیمت و پرداخت و سپس سفارش و شخصی‌سازی غذا و نوشیدنی. هر شش درس یک زنجیرهٔ کاربردی از درخواست تا انتخاب، مقدار، قیمت و ترجیح را می‌سازند و نگه‌داشتن دو واحد سه‌درسی برای یک خانوادهٔ ارتباطی واحد، مرزبندی مصنوعی ایجاد می‌کرد.',
    notes='واحد خرید و سفارش غذا برای حذف مرز سهمیه‌ای ادغام شد؛ درس‌ها و محتوای آلمانی بدون تغییر باقی مانده‌اند.'
WHERE language_level_id=@level AND unit_key='de-a1-unit-shopping-quantity-payment';
UPDATE units
SET title_fa='مسیر، مکان‌های عمومی و حمل‌ونقل',
    grouping_rationale='این واحد شش درس دارد چون حرکت در شهر یک توالی واحد می‌سازد: ابتدا پیدا کردن مکان و پرسیدن/فهم مسیر، سپس استفاده از همان دانش مکانی برای بلیت، وسیله، توقف، زمان و سکو. حمل‌ونقل عمومی از نظر پیش‌نیاز به مسیر و مقصد وابسته است؛ بنابراین ادغام این دو خوشه یک توالی آموزشی طبیعی‌تر از «کجا و چگونه بروم» تا «با چه وسیله و چه زمانی بروم» ایجاد می‌کند.',
    notes='واحد مسیر و حمل‌ونقل بر اساس وابستگی آموزشی ادغام شد؛ متن آلمانی، گفت‌وگو و تمرین‌ها دست‌نخورده‌اند.'
WHERE language_level_id=@level AND unit_key='de-a1-unit-directions-public-places';
UPDATE units
SET title_fa='درخواست کمک، خدمات و سلامت',
    grouping_rationale='این واحد شش درس دارد چون همهٔ درس‌ها حول درخواست کمک و دریافت خدمت در موقعیت واقعی می‌چرخند: روشن‌سازی و اجازه، خدمات روزمره و پیدا کردن پزشک، سپس بیان علامت، دارو و پیگیری حال. بخش سلامت ادامهٔ طبیعیِ نیاز به کمک و خدمات ضروری است و ادغام آن از ساخت دو واحد هم‌اندازه صرفاً به‌خاطر موضوع جلوگیری می‌کند.',
    notes='واحد خدمات و سلامت برای ساخت توالی آموزشی درخواست کمک تا دریافت خدمت ضروری ادغام شد؛ هیچ متن آلمانی تغییر نکرده است.'
WHERE language_level_id=@level AND unit_key='de-a1-unit-requests-services-help';
COMMIT;

