SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

UPDATE language_levels
SET notes='A1 شامل ۹ واحد و ۳۹ درس است. قانون ثابتِ تمرین اول به‌صورت گفت‌وگوی گفتاری حفظ شده و تمرین‌های بعدی همچنان نیازمحور هستند. در بازبینی جدید فقط به ۶ درس که شکاف تمرینی مشخص داشتند تمرین اضافه شد؛ تعداد کل تمرین‌ها از ۱۳۴ به ۱۴۰ رسید. هیچ متن آلمانی ساخته یا بازنویسی نشد.',
    completion_assessment='{"reviewedAt":"2026-09-19T07:23:00Z","cefrCoverageComplete":true,"progressionComplete":true,"practiceAndRetrievalComplete":false,"skillModeCoverageComplete":false,"requiredGaps":["تمرین مستقل شنیداری و تلفظ نسبت به قبل بهتر شده، اما در مقیاس ۳۹ درس هنوز پوشش کافی و توزیع گسترده‌ای ندارد.","بازیابی تجمعی اکنون سه ایستگاه مرور بین‌واحدی دارد، اما هنوز به اندازهٔ کافی گسترده و نظام‌مند نیست."],"qualityReview":{"overallScore":8.4,"dimensionScores":{"cefrCoverage":8.8,"pedagogicalProgression":8.6,"practiceAndRetrieval":7.2,"activityQualityAndVariety":8.3,"linguisticAccuracyAndNaturalness":9.2,"sourceQualityAndCurrency":8.2,"learnerSupportAndClarity":8.7,"qaIntegrity":9.4},"rationale":"بازبینی جدید قانون «گفت‌وگوی ثابت در جایگاه اول، طراحی داینامیک از تمرین دوم به بعد» را حفظ می‌کند و فقط در ۶ درس با شکاف مشخص تمرین تازه اضافه می‌کند: تمایز نیاز/خرید، تحصیل/زندگی، Ihr/Ihre در پاسخ جمع، تأیید هویت، پاسخ محل دارو و پاسخ کوتاه توقف قطار. تعداد کل تمرین‌های A1 اکنون ۱۴۰ است. تمرین‌های جدید یا از گزینه‌های عین منبع استفاده می‌کنند یا تبدیل مکانیکی مجاز روی جملهٔ منبع‌دار هستند؛ هیچ متن آلمانی تازه‌ای تولید نشده است. ضعف‌های اصلی باقی‌مانده همچنان پوشش محدود شنیدن مستقل، تلفظ و بازیابی تجمعی‌اند.","strengths":["هر ۳۹ درس با یک گفت‌وگوی منبع‌دار آغاز می‌شود و تنها این جایگاه ساختاری ثابت است.","از تمرین دوم به بعد، تعداد و نوع تمرین بر اساس نیاز آموزشی همان درس انتخاب می‌شود؛ در این بازبینی فقط ۶ درس با شکاف روشن گسترش یافتند.","تمرین‌های تازه از متن‌های منبع‌دار موجود یا تبدیل‌های مکانیکی مجاز ساخته شده‌اند و هیچ متن آلمانی تازه‌ای تولید نشده است.","۹ واحد و ۳۹ درس با اندازه‌های متفاوت، موقعیت‌های ارتباطی اصلی A1 را با گروه‌بندی نیازمحور پوشش می‌دهند.","فعالیت تطبیق حالت صریح دارد و زبان هر دو سمت توسط قرارداد محتوایی کنترل می‌شود.","تمرین مستقل شنیداری در چند حوزهٔ متفاوت وجود دارد و تمرین تلفظ از الفبا فراتر رفته است.","سه ایستگاه مرور و بازیابی بین‌واحدی در نیمهٔ دوم سطح A1 وجود دارد."],"remainingWeaknesses":["مرتب‌سازی کلمات هنوز در ۲۷ درس دیده می‌شود، اما دیگر پایان یا الگوی اجباری همهٔ درس‌ها نیست و باید در توسعه‌های بعدی فقط وقتی نیاز آموزشی روشن دارد حفظ شود.","تمرین مستقل شنیداری با ۱۰ فعالیت و تلفظ با ۳ فعالیت برای ۳۹ درس هنوز کم است.","بازیابی تجمعی فقط سه ایستگاه مرور بین‌واحدی دارد و هنوز پوشش نظام‌مند کل مسیر نیست.","نوشتن آزاد در انواع فعالیت فعلی پشتیبانی نمی‌شود و فقط تمرین نوشتاری هدایت‌شده قابل ادعاست.","پوشش واژگان با فهرست رسمی واژگان سطح A1 مؤسسهٔ گوته هنوز به‌صورت موردبه‌مورد ممیزی نشده است."]},"scopeExclusions":["ورودی آزاد تایپی در ساختار فعلی فعالیت‌ها پشتیبانی نمی‌شود؛ تولید نوشتاری سطح A1 در این نسخه هدایت‌شده است.","برابری کامل فهرست واژگان با همهٔ مدخل‌های فهرست رسمی واژگان سطح A1 مؤسسهٔ گوته در این بازبینی ادعا نمی‌شود؛ منبع رسمی برای ممیزی آینده ثبت شده است."]}'
WHERE id=@level;

UPDATE lessons
SET sequence_rationale='بعد از گفت‌وگو ابتدا شبکهٔ واژگان حمل‌ونقل مرور می‌شود، سپس پاسخ بله/خیر به پرسش توقف سنجیده می‌شود و در پایان پرسش توقف به تولید هدایت‌شده منتقل می‌شود. تمرین جدید مستقیماً یکی از هدف‌های آموزشیِ قبلاً کم‌سنجیده‌شده را پوشش می‌دهد.'
WHERE language_level_id=@level AND lesson_key='de-a1-lesson-transport-train-bus';
UPDATE activities a JOIN lessons l ON l.id=a.lesson_id
SET a.selection_reason='یکی از هدف‌های صریح درس فهم پاسخ کوتاه مثبت یا منفی به پرسش توقف است؛ دو تمرین قبلی این هدف را مستقل از گفت‌وگو نمی‌سنجیدند. گزینه‌ها عین همان منبع حمل‌ونقل هستند.'
WHERE l.language_level_id=@level AND a.activity_key='act-de-a1-transport-stop-response';

UPDATE lessons
SET activity_selection_rationale='گفت‌وگو دو کاربرد مکان را در خانواده معرفی می‌کند؛ سپس تشخیص جملهٔ تحصیل، تکمیل هدایت‌شدهٔ فعل‌های مربوط به «درس خواندن/زندگی کردن» و در پایان بازسازی پرسش محل زندگی، سه سطح متفاوت از فهم تا تولید هدایت‌شده را پوشش می‌دهند.',
    sequence_rationale='پس از گفت‌وگو ابتدا معنی جمله تشخیص داده می‌شود، سپس فعل مناسب در یک جملهٔ منبع‌دار بازیابی می‌شود و در پایان پرسش محل زندگی بازسازی می‌شود. تمرین جدید برای انتقال از تشخیص به بازیابی فعل اضافه شده است.'
WHERE language_level_id=@level AND lesson_key='de-a1-lesson-family-profile-review';
UPDATE activities a JOIN lessons l ON l.id=a.lesson_id
SET a.selection_reason='هدف درس تمایز تحصیل و زندگی است؛ این تمرین جای‌خالی با جملهٔ منبع‌دار، تشخیص معنایی را به بازیابی هدایت‌شدهٔ خودِ فعل منتقل می‌کند.'
WHERE l.language_level_id=@level AND a.activity_key='act-de-a1-family-review-verb-fill';

UPDATE lessons
SET sequence_rationale='پس از گفت‌وگو، ابتدا واژگان پایه تثبیت می‌شوند، سپس ارتباط پرسش «کجا؟» با پاسخ داروخانه سنجیده می‌شود و در پایان پرسش به تولید هدایت‌شده منتقل می‌شود. تمرین جدید شکاف ارتباط سؤال/جواب را پوشش می‌دهد.'
WHERE language_level_id=@level AND lesson_key='de-a1-lesson-health-medicine-pharmacy';

COMMIT;
